import json,pathlib
p=pathlib.Path(__file__).parent
S=[]
def source(id,title,url,kind,note):
 S.append(dict(id=id,title=title,url=url,kind=kind,note=note));return id
source('rotarix','Ruiz-Palacios et al., NEJM, 2006','https://doi.org/10.1056/NEJMoa052434','Randomized trial','63,225 infants; randomized, double-blind, placebo-controlled safety and efficacy study. Manufacturer involvement warrants scrutiny, but does not erase the randomized comparison.')
source('fda','FDA Rotarix prescribing information, sections 5.5 and 6.1','https://www.fda.gov/media/75726/download','Regulatory record','Documents pre-licensure safety testing and postmarketing intussusception findings. The PDF is a historical label, not current prescribing advice.')
source('rotarisk','Yih et al., NEJM, 2014','https://doi.org/10.1056/NEJMoa1303164','Postmarketing study','US infant data identified a small excess intussusception risk after rotavirus vaccination. Large population surveillance can detect risks missed by trials.')
source('mogensen','Mogensen et al., EBioMedicine, 2017','https://doi.org/10.1016/j.ebiom.2017.01.041','Observational study','Historical Guinea-Bissau natural experiment; overall HR 5.00; female subgroup HR 9.98 with a very wide interval. This is evidence supporting concern, not a randomized demonstration of harm.')
source('higgins','Higgins et al., BMJ, 2016','https://www.bmj.com/content/355/bmj.i5170','Systematic review','DTP mortality RR 1.38, 95% CI 0.92 to 2.08, from 10 studies assessed as high risk of bias. Predates the 2017 paper; it is context, not a review of that later paper.')
source('who','WHO SAGE meeting report, April 2014','https://cdn.who.int/media/docs/default-source/immunization/sage/2014/april/apr2014wer8921.pdf?sfvrsn=83c7d7b1_3','Expert evidence review','Found insufficient evidence to change vaccination policy on nonspecific effects; encouraged better research. Also predates the 2017 study.')
source('engels','Engels et al., JNCI, 2003','https://pubmed.ncbi.nlm.nih.gov/12671021/','Population cohort','Danish cancer registry analysis, 69.5 million person-years; no increase in overall cancer incidence associated with historical contaminated-vaccine birth cohorts. Exposure inferred from birth year.')
source('iarc','IARC Monographs, volume 104, SV40 evaluation','https://www.ncbi.nlm.nih.gov/books/NBK294242/','Carcinogenicity review','Sufficient animal evidence, inadequate human evidence; Group 3. Reviews conflicting tumor-PCR results and contamination concerns. Group 3 does not mean proven harmless.')
source('iom','Institute of Medicine, SV40 contamination review, 2002','https://www.ncbi.nlm.nih.gov/books/NBK221118/','Evidence review','Explains that roughly 98 million people received polio vaccine during the relevant period; an estimated 10% to 30% were exposed to live SV40. Historical uncertainties remain.')
source('cdc','CDC historical vaccine concerns','https://www.cdc.gov/vaccine-safety/historical-concerns/','Public health history','Acknowledges SV40 contamination in 1955 to 1963 and subsequent lot-testing requirements. Historical harm deserves direct acknowledgment.')
source('greco','Greco et al., NEJM, 1996','https://doi.org/10.1056/NEJM199602083340601','Randomized trial','Whole-cell DTP caused more local and systemic reactions than acellular formulations; the control received DT, not saline. Product-specific efficacy varied.')
source('gustafsson','Gustafsson et al., NEJM, 1996','https://doi.org/10.1056/NEJM199602083340602','Randomized trial','9,829 infants; more fever, prolonged crying and hypotonic episodes with whole-cell vaccine. Illustrates why formulation and adverse-event definitions matter.')
source('polio','Francis and Korns, 1955 field-trial report','https://pubmed.ncbi.nlm.nih.gov/14376387/','Original trial report','Primary report of the 1954 Salk trial. The historical placebo was a vaccine-like culture-medium preparation; calling it simply saline loses an important detail.')
source('umich','University of Michigan, 1955 trial announcement','https://sph.umich.edu/polio/','Institutional archive','Contemporaneous trial announcement, including safety conclusions. Does not establish that every later formulation or manufacturing lot was safe.')
source('e10','FDA / ICH E10, choice of control group','https://www.fda.gov/regulatory-information/search-fda-guidance-documents/e10-choice-control-group-and-related-issues-clinical-trials','Trial-design guidance','Discusses placebo, active-treatment and other controls. The appropriate comparison depends on the scientific question and ethics.')
source('law','Bruesewitz v. Wyeth, 562 US 223, 2011','https://www.govinfo.gov/app/details/USREPORTS-562/USREPORTS-562-223','Supreme Court opinion','Concerns vaccine design-defect liability and statutory interpretation, not a clinical estimate of vaccine risk. The Court divided over the scope of preemption.')
source('statute','42 USC 300aa-22, manufacturer responsibility','https://www.law.cornell.edu/uscode/text/42/300aa-22','Statutory text','The legal rule distinguishes unavoidable side effects, manufacturing and warnings; it is not a statement that every vaccine causes net harm.')
source('foia','ICAN v. HHS, July 2018 stipulated order','https://childrenshealthdefense.org/wp-content/uploads/rfk-hhs-stipulated-order-july-2018.pdf','Court filing','The request concerned biennial reports to Congress under 42 USC 300aa-27(c), rather than a search for every clinical trial. Hosted by an advocacy organization; inspect the filing itself.')
source('hviid','Hviid et al., JAMA, 2003','https://doi.org/10.1001/jama.290.13.1763','Population cohort','467,450 children; compared thimerosal-containing and thimerosal-free versions of the same vaccine, with no association with autism or dose-response signal. Observational, not randomized.')
source('cioms','CIOMS / WHO, guideline 5, choice of control','https://www.ncbi.nlm.nih.gov/books/NBK614415/','Research ethics guidance','Explains when placebo is justified and why withholding an established effective intervention can be unethical.')
C=[]
def claim(id,time,title,verdict,summary,said,fair,analysis,limits,refs): C.append(dict(id=id,time=time,title=title,verdict=verdict,summary=summary,said=said,fair=fair,analysis=analysis,limits=limits,refs=refs))
claim('safe',19,'Can any vaccine be safe and effective?','Misleading','Safety means a favorable, specified benefit-risk balance. It never means zero possible harm.','Kennedy first allows that some live-virus vaccines probably prevent more problems than they cause, then rejects the broad safe-and-effective description.','He is right that a product can prevent its target disease yet cause other harms. A fair evaluation must count both.','The categorical rejection sets an impossible standard if safe means risk-free. The rotavirus trial showed a large reduction in severe disease while actively assessing adverse events. Later detection of a rare harm refines the balance; it does not erase the measured benefit.','A result for one vaccine, population and endpoint cannot establish safety for every vaccine or person. This review does not offer a universal ranking of vaccines.',['rotarix','rotarisk','fda'])
claim('sv40-exposure',38,'SV40 contamination really happened','Partly supported','The contamination is historical fact. The claim that all 98 million vaccine recipients received SV40 overstates the exposure estimate.','He links historical polio vaccination to SV40 exposure in his generation.','Monkey-kidney cultures contaminated some early polio vaccines. This was a real manufacturing failure, followed by new testing requirements.','The IOM account distinguishes roughly 98 million people vaccinated during the period from the estimated 10% to 30% exposed to live SV40. Vaccine receipt and confirmed contaminated-dose exposure are different quantities.','Contamination estimates are retrospective and uncertain. Modern polio products should not be treated as the same exposure as contaminated 1950s lots.',['iom','cdc'])
claim('sv40-cancer',38,'Did SV40 cause a human cancer epidemic?','Not established','Animal carcinogenicity is real. The proposed large human cancer toll is not supported by the cited epidemiology.','He describes SV40 as extremely carcinogenic and connects contamination to later cancers, while saying he does not know whether the vaccine caused more deaths than it prevented.','SV40 can cause tumors in experimental animals. Early positive findings in human tumor samples were a legitimate reason to investigate.','IARC found inadequate human evidence and classified SV40 as Group 3. A Danish registry study with 69.5 million person-years did not find increased overall cancer incidence in the exposed birth cohorts. A rise in cancer over time alone cannot identify a vaccine cause.','Birth-cohort exposure proxies can misclassify individuals. Null overall results cannot exclude every small, rare, site-specific effect. Group 3 is uncertainty, not proof of harmlessness.',['iarc','engels','iom'])
claim('dtp-formulation',137,'Whole-cell DTP had more reactions','Partly supported','The formulation distinction matters: whole-cell DTP and acellular DTaP are different products.','He says DTP was withdrawn in the US and Europe because it injured children, and links that history to its use in Africa.','Randomized trials found more fever, local reactions and prolonged crying with whole-cell vaccines than with acellular alternatives. Reducing reactogenicity is a legitimate goal.','The 1996 trials document a safety advantage for acellular formulations, alongside variable efficacy. That supports a narrower claim about adverse reactions. It does not establish that whole-cell DTP destroys immunity or that all European countries followed one identical policy.','These trials do not resolve long-term nonspecific mortality. This review has not verified his numbers about African recipients or his account of Reagan-era conversations. Those claims remain unverified here.',['greco','gustafsson'])
claim('legal',150,'Does the law declare vaccines unsafe?','Misleading','A liability rule cannot tell us the probability or balance of clinical harm.','He invokes the 1986 law and Bruesewitz to argue that vaccines cannot be made safe.','Vaccine injuries occur, and the law provides a compensation framework while limiting some manufacturer liability. The tradeoff is open to policy criticism.','Bruesewitz interprets preemption of design-defect lawsuits. The phrase about unavoidable side effects does not establish that every vaccine is more harmful than beneficial. Read the statutory language alongside the divided judicial opinions.','This is a distinction between a legal category and a scientific conclusion, not advice about bringing a legal claim. The reported Reagan dialogue is not independently verified here.',['law','statute'])
claim('dtp-mortality',240,'The tenfold mortality result','Uncertain causal claim','There is a real study behind the number. Kennedy presents a fragile subgroup estimate as a settled general effect.','He says girls given DTP were ten times more likely to die and argues that the vaccine killed more children than the diseases it prevented.','The 2017 study reports higher mortality after DTP. Its authors use vaccination opportunities tied to birthdays and weighing visits as a natural experiment, arguing this reduces selection bias. That is a substantive design argument worth evaluating.','For girls, the estimated hazard ratio was 9.98, with a 95% interval of 0.81 to 123: four vaccinated deaths versus one not-yet-vaccinated death over unequal follow-up. Overall HR was 5.00, interval 1.53 to 16.3. The underlying data are from 1981 to 1983, not 30 years of follow-up. Association alone cannot establish net deaths caused.','The overall association should not be dismissed because the subgroup is imprecise. Remaining confounding, vaccination records, oral-polio coadministration and setting affect interpretation. The 2016 review found high risk of bias and an inconclusive pooled association; it predates this study.',['mogensen', 'higgins', 'who'])
claim('immune',270,'Did DTP ruin the children\'s immune systems?','Not established','The mortality association does not demonstrate the biological mechanism he describes.','He interprets deaths from other infections as evidence that DTP damaged immunity.','Nonspecific vaccine effects are a legitimate research topic. All-cause outcomes can reveal effects missed by disease-specific endpoints.','A mortality comparison alone cannot show immune destruction. Establishing that explanation would require direct mechanistic evidence linked to clinical outcomes, as well as a credible causal estimate. WHO reviews recognized uncertainty about both beneficial and harmful nonspecific effects.','The lack of a demonstrated mechanism does not make an adverse effect impossible. It means this particular explanation goes beyond what the study measured.',['mogensen','higgins','who'])
claim('placebo',315,'No vaccine gets placebo-controlled safety testing?','Contradicted','One clear counterexample defeats this universal claim. Rotarix is one.','He says none of the childhood vaccines underwent placebo-controlled testing before licensure, then distinguishes safety from efficacy.','Comparator ingredients, follow-up duration and measured adverse events matter. Calling a control placebo does not automatically mean it was saline or free of every biologically active ingredient.','The 2006 Rotarix study randomized 63,225 infants before US licensure in 2008, assessing safety and efficacy. FDA documentation explicitly identifies it as a pre-licensure placebo-controlled safety study. The oral control was a matched placebo, not an injection of saline. A safety analysis does not stop being one because a trial also evaluates efficacy.','This is not proof that every childhood vaccine has an inert-placebo trial. Some use active controls. Nor was this trial powered to exclude every rare or delayed adverse event, as subsequent intussusception surveillance illustrates.',['rotarix','fda','rotarisk'])
claim('controls',320,'Must every other medicine use a placebo?','Contradicted','Drug trials can use active controls and other designs too.','He portrays vaccines as uniquely exempt from a universal placebo requirement for other medicines.','An inert control can help estimate total product-attributable risk. An active control can conceal harms that both products share. That is a real design limitation.','ICH E10 discusses several control designs. An active comparison can answer whether a new product is better or no worse than an established one. Withholding proven care may be unethical. The correct criticism names the product, comparator, outcome and missing information.','Active-control evidence cannot automatically answer the question of vaccination versus no vaccination. Ethical arguments do not excuse poor design or inadequate surveillance.',['e10','cioms'])
claim('polio-trial',365,'Was the original polio trial only about efficacy?','Misleading','The 1954 program evaluated safety as well as efficacy; the original control was more specific than the word saline suggests.','After Lex challenges him, Kennedy allows that a pre-licensure polio placebo trial may have existed but excludes it as a safety trial.','A trial does not establish complete safety forever. Later manufacturing failures and SV40 contamination show why trial results cannot replace production quality controls.','The Francis report and the University of Michigan announcement document a pre-licensure evaluation with safety conclusions. The historical placebo was a matched culture-medium preparation. The useful question is what harms were actually monitored and with what sensitivity, rather than whether the paper has the word safety in its title.','The historical trial does not meet every modern standard and cannot rule out cancers with decades of latency. Lex\'s saline shorthand should also be scrutinized.',['polio','umich','cdc'])
claim('foia',470,'What did the HHS lawsuit establish?','Misleading','The publicly linked 2018 filing concerns reports to Congress, not proof that clinical trials do not exist.','He describes an HHS records response as an admission that no pre-licensure safety studies existed.','A failure to locate legally required safety reports would be an accountability problem. It deserves scrutiny on its own terms.','The 2018 stipulated order concerns biennial reports under 42 USC 300aa-27(c). No responsive records for that request does not mean there are no clinical safety studies. The Rotarix trial provides an independently checkable counterexample.','He does not specify a docket in the clip. This assessment concerns the publicly circulated 2018 filing commonly linked to the claim; a different letter would need its own review.',['foia','fda'])
claim('debate',650,'Thimerosal evidence and debate performance','Scope note','A study must examine the exposure in question. A public debate cannot substitute for that check.','Later, Kennedy says Hotez sent MMR studies when the disagreement concerned thimerosal.','If that description is accurate, an MMR-only study would not directly test a thimerosal hypothesis. The private exchange is not available here to verify.','There is direct thimerosal research. Hviid and colleagues compared thimerosal-containing and thimerosal-free versions of the same vaccine in 467,450 children, finding no autism association. That is more relevant than an MMR-only citation.','This does not verify what Hotez sent or rebut every possible thimerosal outcome. The main review covers the scientific opening through roughly eight minutes; later personal and debate claims are not comprehensively audited.',['hviid'])
(p/'site/content.json').write_text(json.dumps(dict(sources=S,claims=C,reviewed='2026-10-28',scope='Main scientific opening, approximately 00:19 to 08:15. Later discussion is included in the transcript but only selectively reviewed.'),indent=2))
